def _res(slug, org, rtype, category, minutes, cover, targets, exposure, en, uz, ru, *, difficulty="BEGINNER",
         evidence=(), featured=False, order=0):
    return {
        "slug": slug, "organization": org, "resource_type": rtype, "category": category, "duration_minutes": minutes,
        "cover_key": cover, "target_signals": targets, "target_exposure": exposure, "difficulty": difficulty,
        "produces_evidence": bool(evidence), "evidence_signals": list(evidence), "featured": featured, "order": order,
        "title": en[0], "short_description": en[1], "content": en[2],
        "translations": {"uz": {"title": uz[0], "short_description": uz[1], "content": uz[2]},
                         "ru": {"title": ru[0], "short_description": ru[1], "content": ru[2]}},
    }


