def _opp(slug, org, otype, category, mode, cover, ages, deadline, program, targets, exposure, en, uz, ru, *,
         loc=None, global_available=False, opens=None, featured=False):
    loc = loc or {}
    return {
        "slug": slug, "organization": org, "opportunity_type": otype, "category": category, "mode": mode,
        "cover_key": cover, "age_min": ages[0], "age_max": ages[1], "deadline_days": deadline, "program_days": program,
        "open_days": opens, "target_signals": targets, "target_exposure": exposure, "global_available": global_available,
        "featured": featured, "city": loc.get("city", ""), "country": loc.get("country", ""),
        "application_url": f"https://example.org/gifted-demo/{slug}",
        "title": en["title"], "short_description": en["short"], "description": en["description"],
        "skills": en["skills"], "eligibility": en["eligibility"], "faqs": en["faqs"],
        "translations": {
            lang: {
                "title": d["title"], "short_description": d["short"], "description": d["description"],
                "skills": d["skills"], "eligibility": d["eligibility"], "faqs": d["faqs"],
                **({"country": loc[lang]["country"]} if loc else {}),
                **({"city": loc[lang]["city"]} if loc.get("city") else {}),
            }
            for lang, d in (("uz", uz), ("ru", ru))
        },
    }


def _faq(*pairs):
    return [{"q": q, "a": a} for q, a in pairs]


